/**
 * Builds src/generated/logo.ts from ../embedme.html, mirroring the website
 * intro: each SVG path is rasterized as a stroke OUTLINE (not a fill), cells
 * are ordered along the stroke by a nearest-neighbor walk, and each carries a
 * normalized reveal time combining per-path stagger with in-path draw order —
 * the same outside-in stroke draw the web animation performs.
 * Requires ImageMagick (`convert`).
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = join(import.meta.dir, "..");
const W = 104;
const H = 104;
const STROKE_WIDTH = 26;
const PATH_STAGGER = 0.1; // fraction of total draw per path index
const DRAW_SHARE = 0.55; // fraction of the timeline each path's own draw takes

const html = readFileSync(join(ROOT, "..", "embedme.html"), "utf8");
const svgMatch = html.match(/<svg[\s\S]*?<\/svg>/);
if (!svgMatch) throw new Error("no <svg> found in embedme.html");

const pathDs = [...svgMatch[0].matchAll(/<path fill="[^"]*" d="([^"]+)"\/>/g)]
  .map((m) => m[1])
  .filter((d) => d !== "M0 0L2000 0L2000 2000L0 2000L0 0Z");
if (pathDs.length === 0) throw new Error("no logo paths found");

interface Cell {
  row: number;
  col: number;
  bits: number;
  t: number;
}

const DOT_BITS = [
  [0x01, 0x08],
  [0x02, 0x10],
  [0x04, 0x20],
  [0x40, 0x80],
];

function rasterize(d: string): { width: number; height: number; pixels: Uint8Array } {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 2000 2000"><path d="${d}" fill="none" stroke="black" stroke-width="${STROKE_WIDTH}"/></svg>`;
  const file = `/tmp/glint-logo-path.svg`;
  writeFileSync(file, svg);
  const proc = Bun.spawnSync(
    ["convert", "-background", "white", file, "-resize", `${W}x${H}`, "-colorspace", "Gray", "-depth", "8", "pgm:-"],
    { stdout: "pipe", stderr: "pipe" },
  );
  if (proc.exitCode !== 0) throw new Error(`convert failed: ${proc.stderr.toString()}`);
  return parsePgm(new Uint8Array(proc.stdout));
}

function cellsForPath(d: string, pathIndex: number, pathCount: number): Cell[] {
  const { width, height, pixels } = rasterize(d);
  const cols = Math.ceil(width / 2);
  const rows = Math.ceil(height / 4);
  const map = new Map<string, { row: number; col: number; bits: number }>();
  for (let py = 0; py < height; py++) {
    for (let px = 0; px < width; px++) {
      if (pixels[py * width + px] >= 128) continue;
      const cx = Math.floor(px / 2);
      const cy = Math.floor(py / 4);
      const k = `${cy},${cx}`;
      const cell = map.get(k) ?? { row: cy, col: cx, bits: 0 };
      cell.bits |= DOT_BITS[py % 4][px % 2];
      map.set(k, cell);
    }
  }
  const cells = [...map.values()];
  if (cells.length === 0) return [];

  // Nearest-neighbor walk gives a pen-drawing order along the stroke.
  const order = new Map<string, number>();
  const remaining = new Set(cells.map((c) => `${c.row},${c.col}`));
  const byKey = new Map(cells.map((c) => [`${c.row},${c.col}`, c]));
  let current = cells.reduce((a, b) => (b.row < a.row || (b.row === a.row && b.col < a.col) ? b : a));
  let idx = 0;
  while (remaining.size > 0) {
    const ck = `${current.row},${current.col}`;
    remaining.delete(ck);
    order.set(ck, idx++);
    if (remaining.size === 0) break;
    let best: { row: number; col: number; bits: number } | null = null;
    let bestDist = Infinity;
    for (const k of remaining) {
      const c = byKey.get(k)!;
      const dist = (c.row - current.row) ** 2 * 4 + (c.col - current.col) ** 2;
      if (dist < bestDist) {
        bestDist = dist;
        best = c;
      }
    }
    current = best!;
  }

  const startT = (pathIndex * PATH_STAGGER) / (1 + (pathCount - 1) * PATH_STAGGER);
  const span = DRAW_SHARE / (1 + (pathCount - 1) * PATH_STAGGER);
  return cells.map((c) => ({
    row: c.row,
    col: c.col,
    bits: c.bits,
    t: Math.min(1, startT + (order.get(`${c.row},${c.col}`)! / cells.length) * span),
  }));
}

const all: Cell[] = [];
pathDs.forEach((d, i) => all.push(...cellsForPath(d, i, pathDs.length)));

let minRow = Infinity;
let maxRow = -Infinity;
let minCol = Infinity;
let maxCol = -Infinity;
for (const c of all) {
  minRow = Math.min(minRow, c.row);
  maxRow = Math.max(maxRow, c.row);
  minCol = Math.min(minCol, c.col);
  maxCol = Math.max(maxCol, c.col);
}
for (const c of all) {
  c.row -= minRow;
  c.col -= minCol;
}

const packed = all.map((c) => [c.row, c.col, c.bits, Math.round(c.t * 1000)]);
const out = `// Generated by scripts/build-logo.ts — do not edit by hand.
// Each entry: [row, col, brailleBits, revealPermille]
export const LOGO_CELLS: number[][] = ${JSON.stringify(packed)};
export const LOGO_ROWS = ${maxRow - minRow + 1};
export const LOGO_COLS = ${maxCol - minCol + 1};
`;
writeFileSync(join(ROOT, "src", "generated", "logo.ts"), out);

// Render the finished frame for visual inspection.
const grid: number[][] = Array.from({ length: maxRow - minRow + 1 }, () =>
  new Array(maxCol - minCol + 1).fill(0),
);
for (const c of all) grid[c.row][c.col] |= c.bits;
console.log(`logo: ${grid.length} rows x ${grid[0].length} cols, ${all.length} cells, ${pathDs.length} paths`);
console.log(
  grid
    .map((row) => row.map((b) => (b === 0 ? " " : String.fromCharCode(0x2800 + b))).join(""))
    .join("\n"),
);

function parsePgm(data: Uint8Array): { width: number; height: number; pixels: Uint8Array } {
  let pos = 0;
  const token = (): string => {
    while (pos < data.length && /\s/.test(String.fromCharCode(data[pos]))) pos++;
    if (String.fromCharCode(data[pos]) === "#") {
      while (pos < data.length && data[pos] !== 10) pos++;
      return token();
    }
    let t = "";
    while (pos < data.length && !/\s/.test(String.fromCharCode(data[pos]))) {
      t += String.fromCharCode(data[pos]);
      pos++;
    }
    return t;
  };
  const magic = token();
  if (magic !== "P5") throw new Error(`expected P5 pgm, got ${magic}`);
  const width = Number(token());
  const height = Number(token());
  token();
  pos++;
  return { width, height, pixels: data.slice(pos, pos + width * height) };
}
